    # Determine the "marker" color (the one that acts as a boundary)
    # It's usually the one that is less frequent or smaller, but looking at D1(2,4->2 st,4 t) and D2(5,8->5 st,8 t)
    # The marker is consistently the color that remains unchanged.
    # In D1: 2 stays. In D2: 5 stays. In D3: 1 stays.
    # This is the minimum value of the two colors present.

    colors = set()
    for r in range(rows):
        for c in range(cols):
            colors.add(grid[r][c])

    if len(colors) != 2:
        return grid

    sorted_colors = sorted(list(colors))
    marker = sorted_colors[0]

    for r in range(rows):
        marker_pos = []
        # Identify all positions of the marker in this row
        for c in range(cols):
            if grid[r][c] == marker:
                marker_pos.append(c)

        if not marker_pos:
            # No markers in this row? (D3 R4 had no markers)
            # Copy row as is, or check global col logic.
            for c in range(cols):
                if grid[r][c] != marker:
                    output[r][c] = grid[r][c]
                else:
                    output[r][c] = grid[r][c]
        else:
            # Within markers -> 3.
            # Before first -> Keep.
            # After last -> Keep.
            for c in range(cols):
                cell = grid[r][c]
                if cell == marker:
                    output[r][c] = marker
                else:
